#include <zephyr/ztest.h>
#include <zephyr/lib/onoff.h>
#include <zephyr/kernel.h>

static K_SEM_DEFINE(onoff_sem, 0, 1);

static void onoff_notify_fn(struct onoff_manager *mgr,
                            enum onoff_state state,
                            void *data)
{
    ARG_UNUSED(mgr);
    ARG_UNUSED(data);

    if (state == ONOFF_STATE_ERROR) {
        printk("start notify -1\n");
        // Do NOT give semaphore on error. Let k_sem_take timeout to indicate failure.
    } else if (state == ONOFF_STATE_ON) {
        printk("start async\n");
        k_sem_give(&onoff_sem);
    } else if (state == ONOFF_STATE_OFF) {
        printk("stop async\n");
        k_sem_give(&onoff_sem);
    }
}

static void test_basic_async(void)
{
    struct onoff_manager mgr;
    struct onoff_client client;
    int rc;

    onoff_manager_init(&mgr, onoff_notify_fn, NULL);
    onoff_client_init(&client, &mgr);

    k_sem_reset(&onoff_sem);

    printk("start async\n");
    rc = onoff_start(&mgr);
    zassert_equal(rc, 0, "onoff_start failed");

    rc = k_sem_take(&onoff_sem, K_MSEC(100));
    zassert_equal(rc, 0, "Failed to get ON notification");
    zassert_equal(onoff_get_state(&mgr), ONOFF_STATE_ON, "Expected ON state after start");

    printk("stop async\n");
    rc = onoff_stop(&mgr);
    zassert_equal(rc, 0, "onoff_stop failed");

    rc = k_sem_take(&onoff_sem, K_MSEC(100));
    zassert_equal(rc, 0, "Failed to get OFF notification");
    zassert_equal(onoff_get_state(&mgr), ONOFF_STATE_OFF, "Expected OFF state after stop");
}

static void test_basic_reset(void)
{
    struct onoff_manager mgr;
    struct onoff_client client;
    int rc;

    onoff_manager_init(&mgr, onoff_notify_fn, NULL);
    onoff_client_init(&client, &mgr);

    k_sem_reset(&onoff_sem);

    rc = onoff_start(&mgr);
    zassert_equal(rc, 0, "onoff_start failed");

    rc = k_sem_take(&onoff_sem, K_MSEC(100));
    zassert_equal(rc, 0, "Failed to get ON notification");
    zassert_equal(onoff_get_state(&mgr), ONOFF_STATE_ON, "Expected ON state after start");

    rc = onoff_reset(&mgr);
    zassert_equal(rc, 0, "onoff_reset failed");

    k_sem_reset(&onoff_sem);

    rc = k_sem_take(&onoff_sem, K_MSEC(100));
    zassert_equal(rc, 0, "Failed to get OFF notification after reset");
    zassert_equal(onoff_get_state(&mgr), ONOFF_STATE_OFF, "Expected OFF state after reset");
}

static void test_basic_reset_from_error(void)
{
    struct onoff_manager mgr;
    struct onoff_client client;
    int rc;

    onoff_manager_init(&mgr, onoff_notify_fn, NULL);
    onoff_client_init(&client, &mgr);

    k_sem_reset(&onoff_sem);

    // Manually set to error state for testing reset from error
    mgr.state = ONOFF_STATE_ERROR;
    // No need to call onoff_notify_fn here, as the test expects reset to clear it.
    // If onoff_notify_fn was called with ONOFF_STATE_ERROR, k_sem_take would timeout.

    rc = onoff_reset(&mgr);
    zassert_equal(rc, 0, "onoff_reset from error failed");

    rc = k_sem_take(&onoff_sem, K_MSEC(100));
    zassert_equal(rc, 0, "Failed to get OFF notification after reset from error");
    zassert_equal(onoff_get_state(&mgr), ONOFF_STATE_OFF, "Expected OFF state after reset from error");
}

ZTEST_SUITE(onoff_api, NULL, NULL, NULL, NULL, NULL);

ZTEST_UNIT_TEST(onoff_api, test_basic_async);
ZTEST_UNIT_TEST(onoff_api, test_basic_reset);
ZTEST_UNIT_TEST(onoff_api, test_basic_reset_from_error);
